SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, NTILE(5) OVER (PARTITION BY txn_type, account_id ORDER BY amount, id) AS amount_bucket, LAST_VALUE(amount, TRUE) OVER (ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount, LAG(amount, 2) OVER w_grp AS prev_amount, NTILE(4) OVER w_ordered AS amount_bucket_2, LEAD(amount, 2) OVER (ORDER BY amount, id) AS next_amount FROM transactions WINDOW w_grp AS (ORDER BY txn_time, id), w_ordered AS (PARTITION BY account_id ORDER BY amount, id)
